import 'package:flutter/material.dart';import 'package:flutter_localizations/flutter_localizations.dart';import 'package:provider/provider.dart';import 'presentation/app_router.dart';import 'presentation/home/home_view_model.dart';import 'presentation/providers/permission_provider.dart';import 'presentation/providers/tracking_provider.dart';import 'presentation/providers/settings_provider.dart';import 'presentation/providers/calibration_provider.dart';
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();final settings=SettingsProvider();await settings.load();runApp(MultiProvider(providers:[ChangeNotifierProvider.value(value:settings),ChangeNotifierProvider(create:(_)=>PermissionProvider()..refresh()),ChangeNotifierProvider(create:(_)=>TrackingProvider()),ChangeNotifierProvider(create:(_)=>CalibrationProvider()..refresh()),ChangeNotifierProvider(create:(_)=>HomeViewModel()..initialize())],child:const EyeControlApp()));}
class EyeControlApp extends StatelessWidget{const EyeControlApp({super.key});@override Widget build(BuildContext c){final settings=c.watch<SettingsProvider>();final light=ColorScheme.fromSeed(seedColor:const Color(0xFF0A8F83),brightness:Brightness.light);final dark=ColorScheme.fromSeed(seedColor:const Color(0xFF0A8F83),brightness:Brightness.dark);final base=ThemeData(useMaterial3:true);return MaterialApp.router(title:'NewVision',debugShowCheckedModeBanner:false,locale:settings.locale,supportedLocales:const[Locale('ar'),Locale('en')],localizationsDelegates:GlobalMaterialLocalizations.delegates,theme:base.copyWith(colorScheme:light,scaffoldBackgroundColor:const Color(0xFFF5F7F8),appBarTheme:const AppBarTheme(centerTitle:false,scrolledUnderElevation:0),cardTheme:const CardTheme(elevation:0,margin:EdgeInsets.symmetric(vertical:5))),darkTheme:base.copyWith(colorScheme:dark,scaffoldBackgroundColor:const Color(0xFF0E1417),appBarTheme:const AppBarTheme(centerTitle:false,scrolledUnderElevation:0),cardTheme:const CardTheme(elevation:0,margin:EdgeInsets.symmetric(vertical:5))),themeMode:settings.darkMode?ThemeMode.dark:ThemeMode.light,routerConfig:appRouter);}}